import assert from "node:assert/strict";
import { createPushGate } from "<HOME>/Desktop/Open-Source/projelerim/proactive-gate/bench/head-to-head/results/round5-heldout-sonnet/work/courier-inv-g2-3/bot.mjs";
const u = { id: "u1", timeZone: "Asia/Tokyo", quietStart: "22:00", quietEnd: "07:00", dailyCap: 3 };
const g = createPushGate();
const at = (s) => new Date(s);
// Tokyo = UTC+9. 12:00 UTC = 21:00 JST (ok); 13:00 UTC = 22:00 JST (quiet)
assert.deepEqual(g.attempt(u, at("2026-03-10T12:00:00Z")), { allowed: true, reason: null });
assert.equal(g.attempt(u, at("2026-03-10T13:00:00Z")).reason, "quiet_hours");
assert.equal(g.attempt(u, at("2026-03-10T21:59:00Z")).reason, "quiet_hours"); // 06:59 JST
assert.equal(g.attempt(u, at("2026-03-10T22:00:00Z")).allowed, true); // 07:00 JST, next local day
// cap: local day. 2026-03-10 JST had 1 push; 2 more allowed, 4th denied
assert.equal(g.attempt(u, at("2026-03-10T03:00:00Z")).allowed, true);
assert.equal(g.attempt(u, at("2026-03-10T04:00:00Z")).allowed, true);
assert.equal(g.attempt(u, at("2026-03-10T05:00:00Z")).reason, "daily_cap_reached");
// 14:59 UTC Mar 10 = 23:59 JST quiet; 15:00Z = 00:00 JST Mar 11 quiet; 22:00Z Mar 10 = 07:00 Mar 11 -> already used 1 above (counted Mar 11)
assert.equal(g.attempt(u, at("2026-03-10T23:00:00Z")).allowed, true); // new local day, count resets
// UTC midnight must not reset: New York user
const ny = { id: "u2", timeZone: "America/New_York", quietStart: "22:00", quietEnd: "07:00", dailyCap: 1 };
assert.equal(g.attempt(ny, at("2026-03-10T20:00:00Z")).allowed, true); // 16:00 EDT
assert.equal(g.attempt(ny, at("2026-03-11T02:00:00Z")).reason, "quiet_hours"); // 22:00 EDT
assert.equal(createPushGate().attempt(ny, at("2026-03-11T01:00:00Z")).allowed, true); // independent gate
assert.equal(g.attempt(ny, at("2026-03-11T01:30:00Z")).reason, "daily_cap_reached"); // 21:30 EDT still same day
// same-day quiet window, cap 0, per-call settings, invalid
const h = createPushGate();
const d = { id: "u3", timeZone: "UTC", quietStart: "13:00", quietEnd: "15:00", dailyCap: 0 };
assert.equal(h.attempt(d, at("2026-03-10T14:00:00Z")).reason, "quiet_hours");
assert.equal(h.attempt(d, at("2026-03-10T16:00:00Z")).reason, "daily_cap_reached");
assert.equal(h.attempt({ ...d, dailyCap: 1 }, at("2026-03-10T16:00:00Z")).allowed, true);
assert.equal(h.attempt({ ...d, timeZone: "Nope/Zone" }, at("2026-03-10T16:00:00Z")).reason, "invalid_time_zone");
assert.equal(h.attempt(d, new Date("x")).reason, "invalid_time");
// DST day (US spring forward 2026-03-08), midnight quiet end
const dst = { id: "u4", timeZone: "America/New_York", quietStart: "23:00", quietEnd: "02:30", dailyCap: 5 };
const k = createPushGate();
assert.equal(k.attempt(dst, at("2026-03-08T07:45:00Z")).reason, "quiet_hours"); // 02:45 doesn't exist; 07:45Z = 03:45 EDT
EOF
